import{_ as i,o as a,c as t,a2 as s}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Cloudflared with Custom Domain","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guidelines/getting-started/cloudflared-with-custom-domain.md","filePath":"installation-guidelines/getting-started/cloudflared-with-custom-domain.md"}'),n={name:"installation-guidelines/getting-started/cloudflared-with-custom-domain.md"};function o(l,e,r,d,h,p){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="cloudflared-with-custom-domain" tabindex="-1">Cloudflared with Custom Domain <a class="header-anchor" href="#cloudflared-with-custom-domain" aria-label="Permalink to &quot;Cloudflared with Custom Domain&quot;">​</a></h1><p>This documentation outlines how to set up a <strong>Cloudflare Tunnel (<code>cloudflared</code>)</strong> with <strong>Tradeboard</strong> to receive TradingView alerts securely on your local machine </p><h3 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h3><p>A Cloudflare Tunnel creates a secure, outbound-only connection between your local Tradeboard server and the Cloudflare network. This allows TradingView (which is on the public web) to send HTTP POST requests (Webhooks) to your local machine (<code>localhost:5000</code>) securely.</p><hr><h3 id="_2-installation" tabindex="-1">2. Installation <a class="header-anchor" href="#_2-installation" aria-label="Permalink to &quot;2. Installation&quot;">​</a></h3><p>Install <code>cloudflared</code> on your windows machine using powershell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install via Winget (Windows Package Manager)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">winget install Cloudflare.cloudflared</span></span></code></pre></div><p><em>Note: After installation, restart your terminal to ensure the command is recognized.</em></p><hr><h3 id="_3-configuration-in-tradeboard" tabindex="-1">3. Configuration in Tradeboard <a class="header-anchor" href="#_3-configuration-in-tradeboard" aria-label="Permalink to &quot;3. Configuration in Tradeboard&quot;">​</a></h3><p>Before starting the tunnel, you must tell Tradeboard what its public address will be.</p><ol><li><p>Open your Tradeboard folder in <strong>VS Code</strong>.</p></li><li><p>Open the <code>.env</code> file.</p></li><li><p>Locate the <code>HOST_SERVER</code> variable and update it with your intended domain:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HOST_SERVER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://demo.tradeboard.in&#39;</span></span></code></pre></div><p>Update <code>REDIRECT_URL</code> to match, for example <code>https://demo.tradeboard.in/&lt;broker&gt;/callback</code>, and register that same URL with your broker.</p></li><li><p>Save the file and start Tradeboard with <code>uv run app.py</code>. It listens on port 5000, and the WebSocket proxy on port 8765.</p></li></ol><hr><h3 id="_4-setting-up-the-tunnel-two-options" tabindex="-1">4. Setting Up the Tunnel (Two Options) <a class="header-anchor" href="#_4-setting-up-the-tunnel-two-options" aria-label="Permalink to &quot;4. Setting Up the Tunnel (Two Options)&quot;">​</a></h3><h4 id="option-a-custom-domain-recommended-for-production" tabindex="-1">Option A: Custom Domain (Recommended for Production) <a class="header-anchor" href="#option-a-custom-domain-recommended-for-production" aria-label="Permalink to &quot;Option A: Custom Domain (Recommended for Production)&quot;">​</a></h4><p>This keeps your Webhook URL permanent.</p><ol><li><p><strong>Login to Cloudflare:</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cloudflared tunnel login</span></span></code></pre></div><p><em>A browser window will open. Select your domain to authorize.</em></p></li><li><p><strong>Create the Tunnel:</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cloudflared tunnel create tradeboard</span></span></code></pre></div><p><em>This generates a JSON credentials file. Note the path provided in the terminal.</em></p></li><li><p><strong>Configure <code>config.yml</code>:</strong> In your Tradeboard project, locate or create <code>.cloudflared/config.yml</code> and fill it:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tunnel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;YOUR-TUNNEL-ID&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">credentials-file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">C:\\Users\\&lt;Name&gt;\\.cloudflared\\&lt;TUNNEL-ID&gt;.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ingress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">hostname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">demo.tradeboard.in</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://127.0.0.1:5000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http_status:404</span></span></code></pre></div></li><li><p><strong>Route DNS:</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cloudflared tunnel route dns tradeboard demo.tradeboard.in</span></span></code></pre></div></li><li><p><strong>Run the Tunnel:</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cloudflared tunnel </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config .\\.cloudflared\\config.yml run tradeboard</span></span></code></pre></div></li></ol><hr><h4 id="option-b-free-temporary-tunnel-quick-testing" tabindex="-1">Option B: Free Temporary Tunnel (Quick Testing) <a class="header-anchor" href="#option-b-free-temporary-tunnel-quick-testing" aria-label="Permalink to &quot;Option B: Free Temporary Tunnel (Quick Testing)&quot;">​</a></h4><p>If you don&#39;t own a domain, you can generate a random public URL.</p><ol><li><p><strong>Run the command:</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cloudflared tunnel </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span></span></code></pre></div></li><li><p>Cloudflare will generate a URL like <code>https://random-words-generated.trycloudflare.com</code>.</p></li><li><p><strong>Warning:</strong> Every time you restart this tunnel, the URL will change. You will have to update your TradingView Webhook URL and <code>.env</code> file accordingly.</p></li></ol><hr><h3 id="_5-integrating-with-tradingview" tabindex="-1">5. Integrating with TradingView <a class="header-anchor" href="#_5-integrating-with-tradingview" aria-label="Permalink to &quot;5. Integrating with TradingView&quot;">​</a></h3><p>Once the tunnel is &quot;Active&quot; in your terminal:</p><ol><li><strong>Get Webhook URL:</strong> Your URL will be <code>https://yourdomain.com/api/v1/placeorder</code>.</li><li><strong>Generate Payload:</strong><ul><li>Go to Tradeboard Local Dashboard -&gt; <strong>Platforms</strong> -&gt; <strong>TradingView</strong>.</li><li>Configure your symbol (e.g., <code>SILVERMARFUT</code>), action (<code>BUY</code>), and quantity.</li><li>Click <strong>Generate JSON</strong> and Copy the code.</li></ul></li><li><strong>Create Alert in TradingView:</strong><ul><li>Set your Condition (e.g., Price Crossing).</li><li>Under <strong>Notifications</strong>, check <strong>Webhook URL</strong> and paste your tunnel URL.</li><li>Under <strong>Message</strong>, paste the JSON payload generated by Tradeboard.</li></ul></li></ol><hr><h3 id="_6-verification-performance" tabindex="-1">6. Verification &amp; Performance <a class="header-anchor" href="#_6-verification-performance" aria-label="Permalink to &quot;6. Verification &amp; Performance&quot;">​</a></h3><ul><li><strong>Order Book:</strong> When the alert triggers, check the <strong>Order Book</strong> tab in Tradeboard to see the executed trade.</li><li><strong>Latency Monitor:</strong> Go to <strong>Logs</strong> -&gt; <strong>Latency Monitor</strong>. <ul><li>Cloudflare Tunnels typically offer latency between <strong>150ms to 300ms</strong>, which is faster than Ngrok or Pagekite in many regions.</li></ul></li><li><strong>Security:</strong> Because the tunnel is outbound-only, your local IP address remains hidden from the public internet.</li></ul><hr><h3 id="_7-troubleshooting" tabindex="-1">7. Troubleshooting <a class="header-anchor" href="#_7-troubleshooting" aria-label="Permalink to &quot;7. Troubleshooting&quot;">​</a></h3><ul><li><strong>404 Error:</strong> Ensure the <code>service</code> URL in <code>config.yml</code> matches the port Tradeboard is running on (default is <code>5000</code>).</li><li><strong>HTTPS Requirement:</strong> TradingView <strong>requires</strong> an <code>https</code> URL. Ensure you use the Cloudflare provided link and not your local IP.</li><li><strong>Tunnel Fails to Start:</strong> Check if another instance of <code>cloudflared</code> is running in the background.</li></ul>`,32)])])}const u=i(n,[["render",o]]);export{g as __pageData,u as default};
